// Obtener respuesta de Gemini
const response = $input.first().json;

console.log('📥 Respuesta de Gemini:', JSON.stringify(response, null, 2));

// Extraer el contenido del mensaje
let content = '';
if (response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts) {
  content = response.candidates[0].content.parts[0].text;
} else {
  throw new Error('Respuesta de Gemini inválida');
}

console.log('📄 Contenido:', content);

// Parsear JSON
let storyData;
try {
  // Limpiar la respuesta de posibles markdown
  const cleanResponse = content
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  console.log('🧹 Respuesta limpia:', cleanResponse);

  storyData = JSON.parse(cleanResponse);

  // Validar que tenga los campos necesarios
  if (!storyData.title || !storyData.story) {
    throw new Error('Respuesta incompleta de Gemini');
  }

  console.log('✅ JSON parseado correctamente');

} catch (error) {
  console.error('❌ Error al parsear JSON:', error.message);
  console.error('📄 Respuesta original:', content);

  // Fallback: usar la respuesta como texto plano
  storyData = {
    title: "Historia Mágica",
    story: content,
    imagePrompt: "Una escena mágica de un cuento infantil"
  };
}

// Retornar datos estructurados
const result = {
  title: storyData.title,
  content: storyData.story,
  imagePrompt: storyData.imagePrompt || "Una escena mágica de un cuento infantil",
  imageUrl: "",
  timestamp: new Date().toISOString(),
  success: true
};

console.log('📤 Respuesta final:', result);

return { json: result };
